    [9527]={name="Spellshifter Rod",quality=3,ilvl=46,sourceType="quest_reward",instructions="Reward from the quest 'Tiara of the Deep'.",zone="Zul'Farrak",questName="Tiara of the Deep",lore="Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it."},
    [9534]={name="Engineer's Guild Headpiece",quality=3,ilvl=47,sourceType="quest_reward",instructions="Reward from the quest 'Divino-matic Rod'. Pick it over the other reward choices.",zone="Zul'Farrak",questName="Divino-matic Rod",lore="Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"},
    [9536]={name="Fairywing Mantle",quality=3,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'A Fine Mess'. Pick it over the other reward choices.",zone="Gnomeregan",questName="A Fine Mess",lore="Wha.. What happened? The last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs."},
    [9605]={name="Repairman's Cape",quality=3,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Data Rescue'.",zone="Gnomeregan",questName="Data Rescue",lore="When we fled Gnomeregan, we left so much data behind! Vitally important data! I need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan."},
    [9666]={name="Stronghorn Girdle",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Dark Heart'. Pick it over the other reward choices.",zone="Feralas",questName="Dark Heart",lore="Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal."},
