    [21180]={name="Earthstrike",quality=4,ilvl=66,sourceType="quest_reward",instructions="Reward from the quest 'Champion's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Champion's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them.",proc="Use: Increases your melee and ranged attack power by 280. Â Effect lasts for 20 sec. (2 Min Cooldown)"},
