    [21244]={name="Blessed Qiraji Pugio",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21269]={name="Blessed Qiraji Bulwark",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21372]={name="Stormcaller's Diadem",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Stormcaller's Diadem'.",zone="Ahn'Qiraj",questName="Stormcaller's Diadem",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21373]={name="Stormcaller's Footguards",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Stormcaller's Footguards'.",zone="Ahn'Qiraj",questName="Stormcaller's Footguards",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21374]={name="Stormcaller's Hauberk",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Stormcaller's Hauberk'.",zone="Ahn'Qiraj",questName="Stormcaller's Hauberk",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21375]={name="Stormcaller's Leggings",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Stormcaller's Leggings'.",zone="Ahn'Qiraj",questName="Stormcaller's Leggings",lore="Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."},
    [21376]={name="Stormcaller's Pauldrons",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Stormcaller's Pauldrons'.",zone="Ahn'Qiraj",questName="Stormcaller's Pauldrons",lore="Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"},
    [21400]={name="Cloak of the Gathering Storm",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Cloak of the Gathering Storm'.",zone="Ahn'Qiraj",questName="Cloak of the Gathering Storm",lore="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."},
